using System.Collections.Generic;
using System.Linq;
using UnityEngine;

public interface ITargetFilter
{
    bool IsValid(Transform candidate);
}

public struct RangeFilter : ITargetFilter
{
    public Vector3 Origin;
    public float Range;

    public bool IsValid(Transform candidate) =>
        (candidate.position - Origin).sqrMagnitude <= Range * Range;
}

public class SkillTargetingManager : MonoBehaviour
{
    [SerializeField] private float skillRange = 8f;

    private readonly List<Transform> enemies = new List<Transform>();

    public Transform CurrentTarget { get; private set; }

    public void RegisterEnemy(Transform enemy) => enemies.Add(enemy);

    private void Update()
    {
        Vector3 origin = transform.position;
        RangeFilter filter = new RangeFilter { Origin = origin, Range = skillRange };
        CurrentTarget = FindNearest(filter, origin);
    }

    private Transform FindNearest(ITargetFilter filter, Vector3 origin)
    {
        int activeCount = 0;
        foreach (Transform enemy in enemies)
        {
            if (enemy.gameObject.activeInHierarchy) activeCount++;
        }
        if (activeCount == 0) return null;

        return enemies
            .Where(e => e.gameObject.activeInHierarchy && filter.IsValid(e))
            .OrderBy(e => (e.position - origin).sqrMagnitude)
            .FirstOrDefault();
    }
}

