using System;
using System.Collections.Generic;

public struct Health
{
    public int Current;
    public int Max;

    public Health(int max)
    {
        Current = max;
        Max = max;
    }

    public bool IsDead => Current <= 0;

    /// <summary>Reduces Current by amount, never below 0. Non-positive amounts are ignored.</summary>
    public void TakeDamage(int amount)
    {
        if (amount <= 0) return;
        Current = amount >= Current ? 0 : Current - amount;
    }
}

public sealed class Boss
{
    private Health _health;

    public Boss(int maxHp)
    {
        _health = new Health(maxHp);
    }

    public Health Health => _health;
}

/// <summary>One boss encounter: a barrier protects the boss, minions fight alongside.</summary>
public sealed class Encounter
{
    private readonly List<Health> _minions = new List<Health>();
    private readonly Boss _boss;
    private readonly Health _barrier;

    public Encounter(int bossHp, int barrierHp)
    {
        _boss = new Boss(bossHp);
        _barrier = new Health(barrierHp);
    }

    public int MinionCount => _minions.Count;
    public int BossHp => _boss.Health.Current;
    public int BarrierHp => _barrier.Current;

    /// <summary>Adds a minion and returns its index.</summary>
    public int AddMinion(int hp)
    {
        _minions.Add(new Health(hp));
        return _minions.Count - 1;
    }

    public int GetMinionHp(int index) => _minions[index].Current;

    /// <summary>Single-target hit on one minion.</summary>
    public void HitMinion(int index, int damage)
    {
        _minions[index].TakeDamage(damage);
    }

    /// <summary>
    /// While the barrier is up it takes the whole hit (damage does not overflow to the boss).
    /// Once the barrier is down, the boss takes the damage.
    /// </summary>
    public void HitBoss(int damage)
    {
        if (!_barrier.IsDead)
        {
            _barrier.TakeDamage(damage);
        }
        else
        {
            _boss.Health.TakeDamage(damage);
        }
    }

    /// <summary>Area attack: every minion takes the damage. Returns how many minions are dead afterwards.</summary>
    public int Explode(int damage)
    {
        int dead = 0;
        for (int i = 0; i < _minions.Count; i++)
        {
            HitMinion(i, damage);
            if (_minions[i].IsDead) dead++;
        }
        return dead;
    }
}

