using System;

/// <summary>Session-wide combat event hub. Created once and alive until the game exits.</summary>
public sealed class CombatEvents
{
    public event Action<int> EnemyKilled;

    /// <summary>Number of handlers currently subscribed to EnemyKilled.</summary>
    public int SubscriberCount => EnemyKilled == null ? 0 : EnemyKilled.GetInvocationList().Length;

    public void RaiseEnemyKilled(int enemyId) => EnemyKilled?.Invoke(enemyId);
}

public sealed class Wallet
{
    public int Gold;
}

/// <summary>Per-level quest: pays KillReward gold for every kill while the level is alive.</summary>
public sealed class QuestTracker : IDisposable
{
    public const int KillReward = 10;

    private readonly CombatEvents _events;
    private readonly Wallet _wallet;

    public int Kills { get; private set; }

    public QuestTracker(CombatEvents events, Wallet wallet)
    {
        _events = events;
        _wallet = wallet;
        _events.EnemyKilled += OnEnemyKilled;
    }

    private void OnEnemyKilled(int enemyId)
    {
        Kills++;
        _wallet.Gold += KillReward;
    }

    public void Dispose()
    {
        Kills = 0;
    }
}

/// <summary>Per-level bonus: pays Bonus gold once, for the first kill of the level.</summary>
public sealed class FirstBloodBonus : IDisposable
{
    public const int Bonus = 100;

    private readonly CombatEvents _events;
    private readonly Wallet _wallet;

    public bool Paid { get; private set; }

    public FirstBloodBonus(CombatEvents events, Wallet wallet)
    {
        _events = events;
        _wallet = wallet;
        _events.EnemyKilled += enemyId => PayOnce();
    }

    private void PayOnce()
    {
        _wallet.Gold += Bonus;
        Paid = true;
        Dispose();
    }

    public void Dispose()
    {
        _events.EnemyKilled -= enemyId => PayOnce();
    }
}

/// <summary>One playthrough of a level. Owns the per-level subscribers.</summary>
public sealed class Level : IDisposable
{
    private readonly CombatEvents _events;
    private readonly Wallet _wallet;
    private QuestTracker _quest;
    private FirstBloodBonus _bonus;

    public Level(CombatEvents events, Wallet wallet)
    {
        _events = events;
        _wallet = wallet;
        Start();
    }

    /// <summary>Kills counted by the current attempt.</summary>
    public int QuestKills => _quest.Kills;

    private void Start()
    {
        _quest = new QuestTracker(_events, _wallet);
        _bonus = new FirstBloodBonus(_events, _wallet);
    }

    /// <summary>The player retries: the attempt starts over with fresh trackers.</summary>
    public void Restart()
    {
        Start();
    }

    /// <summary>The level is unloaded. Safe to call more than once.</summary>
    public void Dispose()
    {
        _quest.Dispose();
        _bonus.Dispose();
    }
}

