            if (events.SubscriberCount != 2) return "레벨 시작 직후 구독자 수 기대 2, 결과 " + events.SubscriberCount;
            events.RaiseEnemyKilled(1);
            if (wallet.Gold != 110) return "첫 처치 후 골드 기대 110(보너스 100 + 처치 10), 결과 " + wallet.Gold;
            events.RaiseEnemyKilled(2); events.RaiseEnemyKilled(3);
            if (wallet.Gold != 130) return "3마리 처치 후 골드 기대 130, 결과 " + wallet.Gold;
            if (level.QuestKills != 3) return "QuestKills 기대 3, 결과 " + level.QuestKills;
            return null;
        });
        Run("first-blood-unsubscribes-itself", () =>
        {
            var events = new CombatEvents(); var wallet = new Wallet();
            var level = new Level(events, wallet);
            events.RaiseEnemyKilled(1);
            if (events.SubscriberCount != 1) return "첫 처치 후 구독자 수 기대 1(퀘스트만), 결과 " + events.SubscriberCount;
            events.RaiseEnemyKilled(2);
            if (wallet.Gold != 120) return "두 번째 처치 후 골드 기대 120, 결과 " + wallet.Gold;
            return null;
        });
        Run("dispose-unsubscribes", () =>
        {
            var events = new CombatEvents(); var wallet = new Wallet();
            var level = new Level(events, wallet);
            events.RaiseEnemyKilled(1);
            level.Dispose();
            if (events.SubscriberCount != 0) return "Dispose 후 구독자 수 기대 0, 결과 " + events.SubscriberCount;
            events.RaiseEnemyKilled(2); events.RaiseEnemyKilled(3);
            if (wallet.Gold != 110) return "Dispose된 레벨이 골드를 지급함: 기대 110, 결과 " + wallet.Gold;
            return null;
        });
        Run("dispose-before-first-kill", () =>
        {
            var events = new CombatEvents(); var wallet = new Wallet();
            var level = new Level(events, wallet);
            level.Dispose();
            level.Dispose();
            if (events.SubscriberCount != 0) return "첫 처치 전에 Dispose: 구독자 수 기대 0, 결과 " + events.SubscriberCount;
            events.RaiseEnemyKilled(1);
            if (wallet.Gold != 0) return "Dispose된 레벨이 골드를 지급함: 기대 0, 결과 " + wallet.Gold;
            return null;
        });
        Run("restart-does-not-leak", () =>
        {
            var events = new CombatEvents(); var wallet = new Wallet();
            var level = new Level(events, wallet);
            for (int attempt = 1; attempt <= 50; attempt++)
            {
                if (events.SubscriberCount != 2) return attempt + "번째 시도 시작 시 구독자 수 기대 2, 결과 " + events.SubscriberCount;
                int before = wallet.Gold;
                events.RaiseEnemyKilled(attempt);
                if (wallet.Gold - before != 110) return attempt + "번째 시도의 첫 처치 보상 기대 110, 결과 " + (wallet.Gold - before);
                if (level.QuestKills != 1) return attempt + "번째 시도의 QuestKills 기대 1, 결과 " + level.QuestKills;
                level.Restart();
                if (level.QuestKills != 0) return "Restart 후 QuestKills 기대 0, 결과 " + level.QuestKills;
            }
            events.RaiseEnemyKilled(0); events.RaiseEnemyKilled(0);
            if (wallet.Gold != 50 * 110 + 120) return "50번 재시작 후 총 골드 기대 " + (50 * 110 + 120) + ", 결과 " + wallet.Gold;
            level.Dispose();
            if (events.SubscriberCount != 0) return "마지막 Dispose 후 구독자 수 기대 0, 결과 " + events.SubscriberCount;
            return null;
        });
        Run("other-subscribers-untouched", () =>
        {
            var events = new CombatEvents(); var wallet = new Wallet();
            int heard = 0;
            System.Action<int> other = id => heard++;
            events.EnemyKilled += other;
            var level = new Level(events, wallet);
            events.RaiseEnemyKilled(1);
            level.Restart();
            events.RaiseEnemyKilled(2);
            level.Dispose();
            events.RaiseEnemyKilled(3);
            if (heard != 3) return "레벨과 무관한 다른 구독자가 3번 호출되어야 함: 결과 " + heard;
            if (events.SubscriberCount != 1) return "레벨 Dispose 후 다른 구독자 1개만 남아야 함: 결과 " + events.SubscriberCount;
            if (wallet.Gold != 220) return "골드 기대 220, 결과 " + wallet.Gold;
            return null;
        });
        Run("dispose-during-dispatch", () =>
        {
            var events = new CombatEvents(); var wallet = new Wallet();
            Level level = null;
            const int BossId = 99;
            // Subscribed before the level, so it runs first within one dispatch.
            events.EnemyKilled += id => { if (id == BossId) level.Dispose(); };
            level = new Level(events, wallet);
            events.RaiseEnemyKilled(1);
            if (wallet.Gold != 110) return "첫 처치 후 골드 기대 110, 결과 " + wallet.Gold;
            events.RaiseEnemyKilled(BossId);
            if (wallet.Gold != 110) return "같은 이벤트 발송 중 먼저 Dispose된 레벨이 골드를 지급함: 기대 110, 결과 " + wallet.Gold;
            if (events.SubscriberCount != 1) return "구독자 수 기대 1, 결과 " + events.SubscriberCount;
            return null;
        });
        Run("dispose-during-dispatch-before-first-kill", () =>
        {
            var events = new CombatEvents(); var wallet = new Wallet();
            Level level = null;
            events.EnemyKilled += id => level.Dispose();
            level = new Level(events, wallet);
            events.RaiseEnemyKilled(1);
            if (wallet.Gold != 0) return "발송 도중 Dispose된 레벨이 보너스 또는 처치 보상을 지급함: 기대 0, 결과 " + wallet.Gold;
            if (events.SubscriberCount != 1) return "구독자 수 기대 1, 결과 " + events.SubscriberCount;
            events.RaiseEnemyKilled(2);
            if (wallet.Gold != 0) return "이후 처치에서 골드가 지급됨: " + wallet.Gold;
            return null;
        });
    }
